    color: var(--color-ink-dark);
    display: flex;
    flex-direction: column;
    font-weight: bold;
    inset: auto 1ch 1ch auto;
    justify-content: center;
    max-inline-size: 25ch;
    min-inline-size: 16ch;
    padding: 1ch;
    position: absolute;
    rotate: 5deg;
    transform-origin: top right;
    z-index: 2;

    .cards & {
