ruby -Ilib:test -e '
require "application_system_test_case"
class GeometryCheckTest < ApplicationSystemTestCase
  test "check geometry" do
    sign_in_as(users(:david))
    card = cards(:logo)
    card.reactions.create!(content: "Ship it 🔥", reacter: users(:david))
    card.reactions.create!(content: "🎉", reacter: users(:kevin))

    visit card_url(card)
    rects = page.evaluate_script(<<~JS)
      (() => {
        const r = (sel) => {
          const el = document.querySelector(sel);
          if (!el) return null;
          const b = el.getBoundingClientRect();
          return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) };
        };
        return {
          cardPermaBg: r(".card-perma__bg"),
          card: r(".card-perma .card"),
          cardFooter: r(".card-perma .card__footer"),
          cardMeta: r(".card-perma .card__meta"),
          cardReactions: r(".card-perma .card .reactions"),
          firstReaction: r(".card-perma .card .reaction"),
          firstReactionAvatar: r(".card-perma .card .reaction .avatar"),
          trigger: r(".card-perma .card .reactions__trigger"),
          notchBottom: r(".card-perma__notch--bottom")
        };
      })()
    JS
    puts "=== CARD DETAIL GEOMETRY ==="
    rects.each { |k, v| puts "  #{k}: #{v.inspect}" }

    visit board_url(card.board)
    find("##{dom_id(card.column)} .cards__expander").click
    assert_selector "##{dom_id(card, :article)} .card__boosts"
    col_rects = page.evaluate_script(<<~JS)
      (() => {
        const root = document.querySelector("##{dom_id(card, :article)}");
        const r = (sel) => {
          const el = sel ? root.querySelector(sel) : root;
          if (!el) return null;
          const b = el.getBoundingClientRect();
          return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) };
        };
        return {
          card: r(null),
          footer: r(".card__footer"),
          meta: r(".card__meta"),
          boosts: r(".card__boosts"),
          boostIcon: r(".card__boosts .icon"),
          comments: r(".card__comments"),
          commentIcon: r(".card__comments .icon")
        };
      })()
    JS
    puts "=== BOARD COLUMN PREVIEW GEOMETRY ==="
    col_rects.each { |k, v| puts "  #{k}: #{v.inspect}" }
  end
end
' -- --name test_check_geometry

